rows as (
 select n.book, g as no, ''::text as title, n.chapter, n.weeks from n, generate_series(n.f,n.t) g
 union all
 select tt.book, tt.f + (u.ord-1)::int, u.title, tt.chapter, tt.weeks from tt, unnest(tt.titles) with ordinality u(title,ord))
insert into public.items (id,subject,book,book_name,no,title,chapter,label,weeks)
select r.book||'-'||r.no, b.subject, r.book, b.book_name, r.no, r.title, r.chapter,
 case when b.show_no then b.short||' '||r.no||case when r.title<>'' then ' '||r.title else '' end
      when r.book='RYO' then '良問 '||r.title
      when b.subject='physics' then b.short||' '||r.title
      else r.title end,
 r.weeks
from rows r join b using (book)
on conflict (id) do update set subject=excluded.subject,book=excluded.book,book_name=excluded.book_name,no=excluded.no,title=excluded.title,chapter=excluded.chapter,label=excluded.label,weeks=excluded.weeks;insert into public.items (id,subject,book,book_name,no,title,chapter,label,weeks) values
